     8    // Returns a list of all possible paths through the given lists.
     9    //
    10    // For example, given `[[1, 2], [3, 4], [5]]`, this returns:
    11    //
    12    // ```
    13    // [[1, 3, 5],
    14    //  [2, 3, 5],
    15    //  [1, 4, 5],
    16    //  [2, 4, 5]]
    17    // ```
    18    //
    19    // Note: called `paths` in dart-sass
    20    template <class T>
    21    std::vector<std::vector<T>> permutate(
    22      const std::vector<std::vector<T>>& in)
    23    {
    24
    25      size_t L = in.size();
    26      size_t n = 0;
    27      size_t* state = new size_t[L + 1];
    28      std::vector<std::vector<T>> out;
    29
    30      // First initialize all states for every permutation group
    31      for (size_t i = 0; i < L; i += 1) {
    32        if (in[i].size() == 0) return {};
    33        state[i] = in[i].size() - 1;
    34      }
    35      while (true) {
    36        std::vector<T> perm;
    37        // Create one permutation for state
    38        for (size_t i = 0; i < L; i += 1) {
    39          perm.push_back(in.at(i).at(in[i].size() - state[i] - 1));
    40        }
    41        // Current group finished
    42        if (state[n] == 0) {
    43          // Find position of next decrement
    44          while (n < L && state[++n] == 0) {}
    45
    46          if (n == L) {
    47            out.push_back(perm);
    48            break;
    49          }
    50
    51          state[n] -= 1;
    52
    53          for (size_t p = 0; p < n; p += 1) {
    54            state[p] = in[p].size() - 1;
    55          }
    56
    57          // Restart from front
    58          n = 0;
    59
    60        }
    61        else {
    62          state[n] -= 1;
    63        }
    64        out.push_back(perm);
    65      }
    66
    67      delete[] state;
    68      return out;
    69    }
